namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = [];

    public NotificationService()
    {
        // Seed initial fake data
        _notifications.AddRange(
        [
            new(NextId(), "Welcome to the app!", DateTime.UtcNow.AddMinutes(-10)),
            new(NextId(), "Your profile was updated.", DateTime.UtcNow.AddMinutes(-5)),
            new(NextId(), "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-2)),
        ]);
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastId)
    {
        lock (_notifications)
        {
            var newer = _notifications.Where(n => n.Id > lastId).ToList();
            return Task.FromResult(newer);
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called internally by the polling loop or externally for testing.
    /// </summary>
    public Task<Notification?> CheckForNewNotificationAsync()
    {
        // Simulate a ~30% chance of a new notification each poll
        if (Random.Shared.Next(0, 10) < 3)
        {
            var notification = new Notification(
                NextId(),
                $"Something happened at {DateTime.UtcNow:HH:mm:ss}",
                DateTime.UtcNow);

            lock (_notifications)
            {
                _notifications.Add(notification);
            }

            return Task.FromResult<Notification?>(notification);
        }

        return Task.FromResult<Notification?>(null);
    }

    private int NextId() => _nextId++;
}

